/* === DYNAMIC SERVICES SECTION (AWWWARDS STYLE, SELF-CONTAINED) === */
(function () {
  var STYLES = `
  .lv-services{position:relative;padding:6rem 1.5rem;max-width:1400px;margin:0 auto;border-top:1px solid rgba(255,255,255,.08);font-family:'Inter',system-ui,-apple-system,sans-serif;}
  @media(min-width:640px){.lv-services{padding:8rem 3rem;}}
  .lv-services *{box-sizing:border-box;}
  .lv-services__glow{position:absolute;top:-6rem;left:50%;transform:translateX(-50%);width:600px;max-width:90%;height:300px;background:rgba(245,158,11,.06);filter:blur(120px);border-radius:9999px;pointer-events:none;z-index:0;}
  .lv-services__head{position:relative;z-index:1;max-width:48rem;margin:0 0 5rem;}  
  .lv-services__intro{font-size:1.05rem;line-height:1.7;color:#a3a3a3;max-width:38rem;margin:0;}
  .lv-services__groups{position:relative;z-index:1;display:flex;flex-direction:column;gap:4rem;}
  .lv-group__header{display:flex;align-items:baseline;justify-content:space-between;gap:1rem;border-bottom:1px solid rgba(255,255,255,.14);padding-bottom:1rem;margin-bottom:2rem;}
  .lv-group__title{font-family:'LeMurmure',Georgia,'Times New Roman',serif;font-weight:400;font-size:clamp(1.35rem,3vw,1.85rem);letter-spacing:.01em;color:rgba(254,243,199,.92);margin:0;}
  .lv-group__index{flex-shrink:0;font-family:ui-monospace,'SFMono-Regular',Menlo,monospace;font-size:.7rem;letter-spacing:.18em;text-transform:uppercase;color:#737373;}
  .lv-grid{display:grid;grid-template-columns:1fr;gap:1.25rem;}
  @media(min-width:768px){.lv-grid{grid-template-columns:repeat(2,1fr);}}
  @media(min-width:1024px){.lv-grid{grid-template-columns:repeat(3,1fr);}}
  .lv-card{position:relative;padding:2rem;border-radius:1rem;background:rgba(23,23,23,.4);border:1px solid rgba(255,255,255,.08);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);transition:border-color .35s ease,background .35s ease,transform .35s ease;}
  .lv-card:hover{border-color:rgba(253,230,138,.3);background:rgba(23,23,23,.82);transform:translateY(-3px);}
  .lv-card__title{font-size:1.05rem;font-weight:500;color:#f5f5f5;margin:0 0 .75rem;transition:color .35s ease;}
  .lv-card:hover .lv-card__title{color:#fde68a;}
  .lv-card__text{font-size:.875rem;line-height:1.65;color:#a3a3a3;margin:0;}
  `;

  var groups = [
    {
      index: "01",
      title: "Brand Identity & Design",
      items: [
        { title: "Logo & Visual Identity", text: "Logo development with a bespoke colour palette and typography — multiple logo concepts refined through feedback rounds until the final direction is right." },
        { title: "Brandbook", text: "A complete brand guide: logo system, colour palette, typography, iconography, email signature, business card, real application examples and clear usage rules." },
        { title: "Social & Document Templates", text: "Presentation decks, social covers, post and carousel templates, and letterhead documents. Delivered as editable source files (AI, PSD) and ready to drop into Canva." }
      ]
    },
    {
      index: "02",
      title: "Web Design & Development",
      items: [
        { title: "Custom Website Design", text: "Responsive, modern, animated design tailored to your brand and engineered for speed, accessibility and conversion — with UX architecture, strategic CTAs, contact forms, live chat, social proof, blog and legal pages." },
        { title: "Online Store", text: "Everything in the website package plus a full store setup, secure payment integration, courier and automated invoicing, and hands-on training to manage products and orders yourself." },
        { title: "Content & Visuals", text: "AI-assisted copy edited by hand, photo manipulation and collages, brand-aligned imagery and image optimisation so every page feels considered." }
      ]
    },
    {
      index: "03",
      title: "Generative & Answer Engine Optimization",
      items: [
        { title: "GEO Research", text: "In-depth research into generative search behaviour, entity mapping and how AI engines discover and cite sources within your niche." },
        { title: "Generative Engine Optimization", text: "Structuring content, technical data and authority signals to maximise your visibility across large language models and AI-powered search results." },
        { title: "Answer Engine Optimization", text: "Conversational content, direct answers and rich schema markup optimised for featured snippets and voice / answer search engines." }
      ]
    },
    {
      index: "04",
      title: "(Local) Search Engine Optimization",
      items: [
        { title: "On-Page SEO", text: "Strategic short, medium and long-tail keyword research, XML sitemap, robots.txt, search-friendly URLs, meta-content, semantic hierarchy and keyword density control." },
        { title: "Google Business Profile", text: "Profile claim and optimisation — description, categories, services and optimised photography — to win the local map pack and drive nearby customers." },
        { title: "Monitoring & Reporting", text: "Ongoing Search Console analysis, competitor audits, schema markup and ranking adjustments to keep momentum after launch." }
      ]
    }
  ];

  function esc(s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  function buildHTML() {
    var groupsHTML = groups.map(function (g) {
      var cards = g.items.map(function (it) {
        return (
          '<article class="lv-card">' +
            '<h4 class="lv-card__title">' + esc(it.title) + '</h4>' +
            '<p class="lv-card__text">' + esc(it.text) + '</p>' +
          '</article>'
        );
      }).join("");
      return (
        '<div class="lv-group">' +
          '<div class="lv-group__header">' +
            '<h3 class="lv-group__title">' + esc(g.title) + '</h3>' +
            '<span class="lv-group__index">' + esc(g.index) + '</span>' +
          '</div>' +
          '<div class="lv-grid">' + cards + '</div>' +
        '</div>'
      );
    }).join("");

    return (
      '<section id="services" class="lv-services" aria-labelledby="lv-services-title">' +
        '<div class="lv-services__glow" aria-hidden="true"></div>' +
        '<header class="lv-services__head">' +
          '<span class="text-[0.7rem] font-medium uppercase tracking-[0.3em] text-neutral-500">What I Offer</span>' +
          '<h2 id="lv-services-title" class="mt-6 text-balance font-serif text-[clamp(3rem,7.5vw,6.75rem)] leading-[1.02] tracking-[-0.01em] text-neutral-50">Services</h2>' +
          '<p class="lv-services__intro">Considered, end-to-end solutions for your brand\u2019s digital presence \u2014 from identity and web design to generative, answer and local search optimization.</p>' +
        '</header>' +
        '<div class="lv-services__groups">' + groupsHTML + '</div>' +
      '</section>'
    );
  }

  function injectStyles() {
    if (document.getElementById("lv-services-styles")) return;
    var style = document.createElement("style");
    style.id = "lv-services-styles";
    style.textContent = STYLES;
    document.head.appendChild(style);
  }

  function injectServices() {
    if (document.getElementById("services")) return; // prevent duplicate injection
    injectStyles();

    var html = buildHTML();
    var contact = document.querySelector("#contact") || document.querySelector("footer");
    var voices = document.querySelector("#voices");

    if (contact) {
      contact.insertAdjacentHTML("beforebegin", html);
    } else if (voices) {
      voices.insertAdjacentHTML("afterend", html);
    } else {
      var root = document.getElementById("root");
      if (root) root.insertAdjacentHTML("beforeend", html);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", injectServices);
  } else {
    injectServices();
  }

  // Ensure injection even if React finishes rendering late.
  var tries = 0;
  var checkInterval = setInterval(function () {
    tries++;
    if (document.getElementById("services") || tries > 40) {
      clearInterval(checkInterval);
    } else {
      injectServices();
    }
  }, 300);
})();
